def transform(grid):
    n = len(grid[0])
    center = grid[0].index(2)
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        for c in (center - r, center + r):
            if 0 <= c < n:
                out[r][c] = 2
        for c in range(n):
            x = c - center
            if (x - r) % 4 == 0 and 2 - r <= x <= r and out[r][c] == 0:
                out[r][c] = 1
    return out
